use super::*;
pub(super) struct EditorTools {pub scene:bool,pub inspector:bool,pub bottom:bool,pub grid:bool,pub colliders:bool,pub search:String,pub snap:f32,pub axis:usize}
impl Default for EditorTools {fn default()->Self{Self{scene:true,inspector:true,bottom:true,grid:true,colliders:false,search:String::new(),snap:16.,axis:0}}}
pub(super) fn valid_parent(p:&Project,selected:Option<Uuid>,candidate:Uuid)->bool{let mut cursor=Some(candidate);let mut seen=std::collections::HashSet::new();while let Some(id)=cursor{if Some(id)==selected||!seen.insert(id){return false;}cursor=p.objects.iter().find(|o|o.id==id).and_then(|o|o.parent);}true}
pub(super) fn delete_selected(e:&mut Editor){if let Some(id)=e.selected.take(){let parent=e.project.objects.iter().find(|o|o.id==id).and_then(|o|o.parent);e.project.objects.retain(|o|o.id!=id);for o in &mut e.project.objects{if o.parent==Some(id){o.parent=parent;}}}}
pub(super) fn duplicate(e:&mut Editor){if let Some(mut o)=e.project.objects.iter().find(|o|Some(o.id)==e.selected).cloned(){o.id=Uuid::new_v4();o.name=format!("{} Copy",o.name);o.position[0]+=e.tools.snap;o.position[1]+=e.tools.snap;e.selected=Some(o.id);e.project.objects.push(o);}}
pub(super) fn focus(e:&mut Editor){if let Some(o)=e.project.objects.iter().find(|o|Some(o.id)==e.selected){let p=project_point(o.position,e.project.isometric);e.pan=egui::vec2(-p[0]*e.zoom,p[1]*e.zoom);}}
pub(super) fn iso_grid(p:&egui::Painter,r:egui::Rect,origin:egui::Pos2,z:f32){let corners=[r.left_top(),r.right_top(),r.left_bottom(),r.right_bottom()];let mut lo=[f32::INFINITY;2];let mut hi=[f32::NEG_INFINITY;2];for c in corners{let d=c-origin;let q=unproject_point([d.x/z,-d.y/z],true);for i in 0..2{lo[i]=lo[i].min(q[i]);hi[i]=hi[i].max(q[i]);}}let step=if z<0.5{128.}else{32.};let screen=|q:[f32;2]|{let q=project_point(q,true);origin+egui::vec2(q[0]*z,-q[1]*z)};for axis in 0..2{let start=(lo[axis]/step).floor() as i32;let end=(hi[axis]/step).ceil() as i32;for k in start..=end.min(start+512){let mut a=lo;let mut b=hi;a[axis]=k as f32*step;b[axis]=a[axis];p.line_segment([screen(a),screen(b)],egui::Stroke::new(1.,egui::Color32::from_gray(49)));}}}

#[cfg(test)] mod tests {use super::*; #[test] fn prevents_cycle(){let mut e=Editor::default();let a=e.project.objects[0].id;let b=e.project.objects[1].id;e.project.objects[1].parent=Some(a);assert!(!valid_parent(&e.project,Some(a),b));assert!(!valid_parent(&e.project,Some(a),a));} #[test] fn delete_reparents(){let mut e=Editor::default();let a=e.project.objects[0].id;e.project.objects[1].parent=Some(a);e.selected=Some(a);delete_selected(&mut e);assert!(e.project.objects.iter().all(|o|o.id!=a && o.parent!=Some(a)));} #[test] fn duplicates_identity(){let mut e=Editor::default();let a=e.project.objects[0].id;e.selected=Some(a);duplicate(&mut e);assert_ne!(e.selected,Some(a));assert_eq!(e.project.objects.len(),4);}}
